<script setup>
import { computed, onMounted, ref, watch } from 'vue';
import { ArrowLeft, Bell, Bookmark, Check, CheckCircle2, Copy, Globe2, Heart, Home, ImagePlus, MessageCircle, MoreHorizontal, PenLine, Repeat2, Search, Send, Settings, Share2, Trash2, UserRound, Users, X } from '@lucide/vue';

const storageKey = 'kwiker-posts';
const profileStorageKey = 'kwiker-profile';
const settingsStorageKey = 'kwiker-settings';
const communitiesStorageKey = 'kwiker-communities';
const followingStorageKey = 'kwiker-following';
const defaultProfile = { name: 'Maya Brooks', handle: '@mayabrooks', initials: 'MB', color: 'linear-gradient(145deg, #7c5cff, #c149ff)', bio: 'Toujours quelque part entre Los Santos et un bon café ☕', following: 184, followers: 1240, accountType: 'Personne', verified: false };
const starterPosts = [
    { id: 1, author: 'LSPD Los Santos', handle: '@LSPD_LS', initials: 'LP', color: 'linear-gradient(145deg, #2c6bed, #17336e)', accountType: 'Entreprise', verified: true, bio: 'Compte officiel de la police de Los Santos.', followers: 18400, following: 32, text: 'Les rues sont calmes ce soir. Merci à tous les habitants qui nous aident à garder Los Santos sûre. 💙', time: Date.now() - 1000 * 60 * 18, likes: 42, comments: 8, reposts: 12, liked: false, reposted: false, bookmarked: false, commentsList: [] },
    { id: 2, author: 'Weazel News', handle: '@weazelnews', initials: 'WN', color: 'linear-gradient(145deg, #ff3b6b, #7f2046)', accountType: 'Entreprise', verified: true, bio: 'Toute l’actualité de Los Santos.', followers: 26700, following: 84, text: 'FLASH INFO — La circulation est perturbée sur Vespucci Boulevard. Évitez le secteur jusqu’à nouvel ordre. 📰', time: Date.now() - 1000 * 60 * 53, likes: 76, comments: 14, reposts: 31, liked: true, reposted: false, bookmarked: false, commentsList: [] },
    { id: 3, author: 'Benny’s Original Motor Works', handle: '@bennys', initials: 'BO', color: 'linear-gradient(145deg, #ff9d3d, #8d3c1e)', accountType: 'Entreprise', verified: false, bio: 'Atelier automobile et préparations sur mesure.', followers: 6300, following: 146, text: 'Nouvelle semaine, nouveau projet. Passez à l’atelier si vous voulez donner un peu de caractère à votre caisse. 🔧', time: Date.now() - 1000 * 60 * 60 * 3, likes: 128, comments: 22, reposts: 18, liked: false, reposted: true, bookmarked: true, commentsList: [] },
];

const posts = ref([]);
const currentUser = ref({ ...defaultProfile });
const activeTab = ref('Pour toi');
const activeSection = ref('home');
const profileTab = ref('Kwiks');
const searchQuery = ref('');
const isComposerVisible = ref(false);
const isSearchVisible = ref(false);
const isProfileVisible = ref(false);
const viewedProfile = ref(null);
const isSettingsVisible = ref(false);
const isNotificationsVisible = ref(false);
const isCommunitiesVisible = ref(false);
const isAccountEditorVisible = ref(false);
const selectedPost = ref(null);
const selectedPostMenu = ref(null);
const isCommentSheetVisible = ref(false);
const commentDraft = ref('');
const actionNotice = ref('');
const draft = ref({ text: '', image: '' });
const publishNotice = ref('');
const imageInput = ref(null);
const accountDraft = ref({ name: '', handle: '', bio: '' });
const accountNotice = ref('');
const accountSettings = ref({ notifications: true, privateAccount: false });
const joinedCommunities = ref(['los-santos', 'car-meets']);
const followingHandles = ref(['@LSPD_LS']);
const communities = [
    { id: 'los-santos', name: 'Los Santos', description: 'Les infos et discussions de la ville.', members: '12,4k', color: 'linear-gradient(145deg, #1d9bf0, #17336e)' },
    { id: 'car-meets', name: 'Car Meets', description: 'Passionnés de belles mécaniques.', members: '3,8k', color: 'linear-gradient(145deg, #ff9d3d, #8d3c1e)' },
    { id: 'vespucci', name: 'Vespucci Beach', description: 'Le meilleur de la côte ouest.', members: '8,1k', color: 'linear-gradient(145deg, #00ba7c, #075e54)' },
];

const formatCount = (count = 0) => count > 999 ? `${(count / 1000).toFixed(1).replace('.0', '')}k` : count;
const relativeTime = (timestamp) => { const minutes = Math.max(0, Math.round((Date.now() - timestamp) / 60000)); if (minutes < 1) return 'maintenant'; if (minutes < 60) return `${minutes} min`; if (minutes < 1440) return `${Math.round(minutes / 60)} h`; return `${Math.round(minutes / 1440)} j`; };
const isOfficialHandle = (handle) => ['@LSPD_LS', '@weazelnews'].includes(handle);
const normalizePost = (post) => ({ ...post, accountType: post.accountType || (isOfficialHandle(post.handle) ? 'Entreprise' : 'Personne'), verified: Boolean(post.verified || isOfficialHandle(post.handle)), commentsList: Array.isArray(post.commentsList) ? post.commentsList : [], poll: post.poll ? { ...post.poll, options: Array.isArray(post.poll.options) ? post.poll.options : [], votes: Array.isArray(post.poll.votes) ? post.poll.votes : [] } : null });

onMounted(() => {
    try {
        const savedPosts = JSON.parse(localStorage.getItem(storageKey) || 'null');
        posts.value = Array.isArray(savedPosts) && savedPosts.length ? savedPosts.map(normalizePost) : starterPosts;
        const savedProfile = JSON.parse(localStorage.getItem(profileStorageKey) || 'null');
        if (savedProfile && typeof savedProfile === 'object') currentUser.value = { ...defaultProfile, ...savedProfile };
        const savedSettings = JSON.parse(localStorage.getItem(settingsStorageKey) || 'null');
        if (savedSettings && typeof savedSettings === 'object') accountSettings.value = { ...accountSettings.value, ...savedSettings };
        const savedCommunities = JSON.parse(localStorage.getItem(communitiesStorageKey) || 'null');
        if (Array.isArray(savedCommunities)) joinedCommunities.value = savedCommunities;
        const savedFollowing = JSON.parse(localStorage.getItem(followingStorageKey) || 'null');
        if (Array.isArray(savedFollowing)) followingHandles.value = savedFollowing;
    } catch { posts.value = starterPosts; }
});
watch(posts, (value) => { try { localStorage.setItem(storageKey, JSON.stringify(value)); } catch { /* Session only. */ } }, { deep: true });
watch(currentUser, (value) => { try { localStorage.setItem(profileStorageKey, JSON.stringify(value)); } catch { /* Session only. */ } }, { deep: true });
watch(accountSettings, (value) => { try { localStorage.setItem(settingsStorageKey, JSON.stringify(value)); } catch { /* Session only. */ } }, { deep: true });
watch(joinedCommunities, (value) => { try { localStorage.setItem(communitiesStorageKey, JSON.stringify(value)); } catch { /* Session only. */ } }, { deep: true });
watch(followingHandles, (value) => { try { localStorage.setItem(followingStorageKey, JSON.stringify(value)); } catch { /* Session only. */ } }, { deep: true });

const profileIdentity = computed(() => viewedProfile.value || currentUser.value);
const isOwnProfile = computed(() => !viewedProfile.value || viewedProfile.value.handle === currentUser.value.handle);
const isFollowingViewed = computed(() => Boolean(viewedProfile.value && followingHandles.value.includes(viewedProfile.value.handle)));
const profilePosts = computed(() => posts.value.filter((post) => post.handle === profileIdentity.value.handle || post.author === profileIdentity.value.name));
const visiblePosts = computed(() => { const query = searchQuery.value.trim().toLowerCase(); return posts.value.filter((post) => { const matchesSearch = !query || `${post.author} ${post.handle} ${post.text}`.toLowerCase().includes(query); const matchesTab = activeTab.value === 'Pour toi' || followingHandles.value.includes(post.handle) || post.author === currentUser.value.name || post.reposted; const matchesSection = activeSection.value !== 'bookmarks' || post.bookmarked; return matchesSearch && matchesTab && matchesSection; }); });
const ownPosts = computed(() => posts.value.filter((post) => post.author === currentUser.value.name));
const profileReplies = computed(() => posts.value.filter((post) => (post.commentsList || []).some((comment) => comment.author === currentUser.value.name)));
const profileMedia = computed(() => ownPosts.value.filter((post) => post.image));
const notificationItems = computed(() => posts.value.slice(0, 3).map((post, index) => ({ id: `${post.id}-${index}`, initials: post.initials, color: post.color, title: index === 0 ? `${post.author} a publié un nouveau Kwik` : `${post.author} fait parler de lui sur Kwiker`, time: relativeTime(post.time) })));

const openComposer = () => { draft.value = { text: '', image: '' }; publishNotice.value = ''; isComposerVisible.value = true; };
const closeComposer = () => { isComposerVisible.value = false; };
const readImage = (event) => { const file = event.target.files?.[0]; if (!file) return; const reader = new FileReader(); reader.onload = () => { draft.value.image = String(reader.result || ''); }; reader.readAsDataURL(file); };
const publishPost = () => { const text = draft.value.text.trim(); if (!text && !draft.value.image) { publishNotice.value = 'Écris quelque chose ou ajoute une image.'; return; } posts.value.unshift({ id: Date.now(), author: currentUser.value.name, handle: currentUser.value.handle, initials: currentUser.value.initials, color: currentUser.value.color, accountType: currentUser.value.accountType, verified: currentUser.value.verified, text, image: draft.value.image, time: Date.now(), likes: 0, comments: 0, reposts: 0, liked: false, reposted: false, bookmarked: false, commentsList: [] }); closeComposer(); };
const toggleLike = (post) => { post.liked = !post.liked; post.likes += post.liked ? 1 : -1; };
const toggleRepost = (post) => { post.reposted = !post.reposted; post.reposts += post.reposted ? 1 : -1; };
const toggleBookmark = (post) => { post.bookmarked = !post.bookmarked; };
const votePoll = (post, optionIndex) => { if (!post.poll || post.poll.votes.includes(currentUser.value.handle)) return; post.poll.votes.push(currentUser.value.handle); post.poll.selected = optionIndex; };
const openComments = (post) => { selectedPost.value = post; commentDraft.value = ''; isCommentSheetVisible.value = true; };
const closeComments = () => { isCommentSheetVisible.value = false; selectedPost.value = null; };
const addComment = () => { const text = commentDraft.value.trim(); if (!text || !selectedPost.value) return; selectedPost.value.commentsList = selectedPost.value.commentsList || []; selectedPost.value.commentsList.push({ id: Date.now(), author: currentUser.value.name, handle: currentUser.value.handle, initials: currentUser.value.initials, color: currentUser.value.color, text, time: Date.now() }); selectedPost.value.comments += 1; commentDraft.value = ''; };
const openSearch = () => { isSearchVisible.value = !isSearchVisible.value; if (!isSearchVisible.value) searchQuery.value = ''; };
const openSettings = () => { isSettingsVisible.value = true; };
const closeSettings = () => { isSettingsVisible.value = false; isAccountEditorVisible.value = false; };
const openNotifications = () => { isNotificationsVisible.value = true; };
const closeNotifications = () => { isNotificationsVisible.value = false; };
const openCommunities = () => { isCommunitiesVisible.value = true; };
const closeCommunities = () => { isCommunitiesVisible.value = false; };
const setHome = () => { activeSection.value = 'home'; isCommunitiesVisible.value = false; isProfileVisible.value = false; };
const setBookmarks = () => { activeSection.value = 'bookmarks'; isCommunitiesVisible.value = false; isProfileVisible.value = false; };
const toggleCommunity = (community) => { joinedCommunities.value = joinedCommunities.value.includes(community.id) ? joinedCommunities.value.filter((id) => id !== community.id) : [...joinedCommunities.value, community.id]; };
const openPostProfile = (post) => { const accountType = post.accountType || (isOfficialHandle(post.handle) ? 'Entreprise' : 'Personne'); viewedProfile.value = { name: post.author, handle: post.handle, initials: post.initials, color: post.color, accountType, verified: Boolean(post.verified || isOfficialHandle(post.handle)), bio: post.bio || (accountType === 'Entreprise' ? 'Compte professionnel sur Kwiker.' : 'Membre de la communauté de Los Santos.'), followers: post.followers || 0, following: post.following || 0 }; profileTab.value = 'Kwiks'; isProfileVisible.value = true; };
const openOwnProfile = () => { viewedProfile.value = null; profileTab.value = 'Kwiks'; isProfileVisible.value = true; };
const closeProfile = () => { viewedProfile.value = null; isProfileVisible.value = false; };
const toggleFollowViewed = () => { if (!viewedProfile.value) return; followingHandles.value = isFollowingViewed.value ? followingHandles.value.filter((handle) => handle !== viewedProfile.value.handle) : [...followingHandles.value, viewedProfile.value.handle]; };
const openPostMenu = (post) => { selectedPostMenu.value = post; };
const closePostMenu = () => { selectedPostMenu.value = null; };
const deletePost = () => { if (!selectedPostMenu.value || selectedPostMenu.value.author !== currentUser.value.name) return; posts.value = posts.value.filter((post) => post.id !== selectedPostMenu.value.id); closePostMenu(); actionNotice.value = 'Kwik supprimé'; window.setTimeout(() => { actionNotice.value = ''; }, 2200); };
const sharePost = async (post) => { const shareText = `${post.author} ${post.handle}\n${post.text}`.trim(); try { if (navigator.share) await navigator.share({ title: 'Kwiker', text: shareText }); else if (navigator.clipboard) await navigator.clipboard.writeText(shareText); actionNotice.value = navigator.share ? 'Kwik partagé' : 'Texte copié dans le presse-papiers'; } catch { actionNotice.value = 'Partage annulé'; } window.setTimeout(() => { actionNotice.value = ''; }, 2200); };
const copyPostLink = async () => { if (!selectedPostMenu.value) return; try { await navigator.clipboard?.writeText(`kwiker://post/${selectedPostMenu.value.id}`); } catch { /* Clipboard unavailable in preview. */ } closePostMenu(); actionNotice.value = 'Lien du Kwik copié'; window.setTimeout(() => { actionNotice.value = ''; }, 2200); };
const openAccountEditor = () => { accountDraft.value = { name: currentUser.value.name, handle: currentUser.value.handle, bio: currentUser.value.bio }; accountNotice.value = ''; isAccountEditorVisible.value = true; };
const closeAccountEditor = () => { isAccountEditorVisible.value = false; accountNotice.value = ''; };
const saveAccount = () => { const name = accountDraft.value.name.trim(); const handle = accountDraft.value.handle.trim().replace(/\s+/g, '').replace(/^@*/, '@'); const bio = accountDraft.value.bio.trim(); if (name.length < 2 || handle.length < 2) { accountNotice.value = 'Ajoute un nom et un pseudo valides.'; return; } const previousName = currentUser.value.name; const nextProfile = { ...currentUser.value, name, handle, bio, initials: name.split(/\s+/).map((part) => part[0]).join('').slice(0, 2).toUpperCase() }; currentUser.value = nextProfile; posts.value.forEach((post) => { if (post.author === previousName) Object.assign(post, { author: name, handle, initials: nextProfile.initials, color: nextProfile.color }); (post.commentsList || []).forEach((comment) => { if (comment.author === previousName) Object.assign(comment, { author: name, handle, initials: nextProfile.initials, color: nextProfile.color }); }); }); closeAccountEditor(); };
</script>

<template>
    <div class="kwiker-app">
        <template v-if="!isProfileVisible && !isNotificationsVisible && !isCommunitiesVisible && !isSettingsVisible">
            <header class="kwiker-header"><button type="button" class="kwiker-icon-button" aria-label="Ouvrir mon profil" @click="openOwnProfile"><span class="kwiker-avatar kwiker-avatar--tiny" :style="{ background: currentUser.color }">{{ currentUser.initials }}</span></button><div class="kwiker-brand"><span class="kwiker-brand-mark">k</span><strong>Kwiker</strong></div><div class="kwiker-header-actions"><button type="button" class="kwiker-icon-button" aria-label="Rechercher" @click="openSearch"><Search :size="18" /></button><button type="button" class="kwiker-icon-button" aria-label="Notifications" @click="openNotifications"><Bell :size="18" /></button></div></header>
            <div v-if="isSearchVisible" class="kwiker-search"><Search :size="16" /><input v-model="searchQuery" type="search" placeholder="Rechercher sur Kwiker" autofocus /><button type="button" aria-label="Fermer" @click="openSearch"><X :size="15" /></button></div>
            <main class="kwiker-feed"><nav class="kwiker-feed-tabs" role="tablist" aria-label="Fil Kwiker"><button type="button" role="tab" :aria-selected="activeTab === 'Pour toi'" :class="{ 'is-active': activeTab === 'Pour toi' }" @click="activeTab = 'Pour toi'; activeSection = 'home'">Pour toi</button><button type="button" role="tab" :aria-selected="activeTab === 'Abonnements'" :class="{ 'is-active': activeTab === 'Abonnements' }" @click="activeTab = 'Abonnements'; activeSection = 'home'">Abonnements</button></nav>
                <section v-if="visiblePosts.length" class="kwiker-posts"><article v-for="post in visiblePosts" :key="post.id" class="kwiker-post"><button type="button" class="kwiker-avatar-button" :aria-label="`Voir le profil de ${post.author}`" @click="openPostProfile(post)"><span class="kwiker-avatar" :style="{ background: post.color }">{{ post.initials }}</span></button><div class="kwiker-post-body"><header class="kwiker-post-header"><button type="button" class="kwiker-post-author kwiker-post-author-button" :aria-label="`Voir le profil de ${post.author}`" @click="openPostProfile(post)"><strong>{{ post.author }}</strong><Check v-if="post.verified" class="kwiker-verified" :size="11" /><span>{{ post.handle }}</span><span>·</span><time>{{ relativeTime(post.time) }}</time></button><button type="button" aria-label="Options du Kwik" @click="openPostMenu(post)"><MoreHorizontal :size="17" /></button></header><p v-if="post.text" class="kwiker-post-text">{{ post.text }}</p><img v-if="post.image" class="kwiker-post-image" :src="post.image" alt="Image publiée" /><div v-if="post.poll" class="kwiker-poll"><button v-for="(option, optionIndex) in post.poll.options" :key="option" type="button" class="kwiker-poll-option" :class="{ 'is-selected': post.poll.selected === optionIndex }" :disabled="post.poll.votes.includes(currentUser.handle)" @click="votePoll(post, optionIndex)"><span>{{ option }}</span><Check v-if="post.poll.selected === optionIndex" :size="14" /></button><small>{{ post.poll.votes.length ? 'Vote enregistré' : 'Sondage' }}</small></div><div class="kwiker-post-actions"><button type="button" :class="{ 'is-active': post.commentsList?.length }" aria-label="Commenter" @click="openComments(post)"><MessageCircle :size="17" /><span>{{ formatCount(post.comments) }}</span></button><button type="button" :class="{ 'is-reposted': post.reposted }" aria-label="Reposter" @click="toggleRepost(post)"><Repeat2 :size="17" /><span>{{ formatCount(post.reposts) }}</span></button><button type="button" :class="{ 'is-liked': post.liked }" aria-label="Aimer" @click="toggleLike(post)"><Heart :size="17" :fill="post.liked ? 'currentColor' : 'none'" /><span>{{ formatCount(post.likes) }}</span></button><button type="button" :class="{ 'is-saved': post.bookmarked }" aria-label="Enregistrer" @click="toggleBookmark(post)"><Bookmark :size="17" :fill="post.bookmarked ? 'currentColor' : 'none'" /></button><button type="button" aria-label="Partager" @click="sharePost(post)"><Share2 :size="16" /></button></div></div></article></section><div v-else class="kwiker-empty"><Bookmark v-if="activeSection === 'bookmarks'" :size="28" /><Search v-else :size="28" /><strong>{{ activeSection === 'bookmarks' ? 'Aucun signet' : 'Aucun Kwik trouvé' }}</strong><span>{{ activeSection === 'bookmarks' ? 'Enregistre un Kwik pour le retrouver ici.' : 'Essaie une autre recherche ou consulte le fil Pour toi.' }}</span></div>
            </main><nav class="kwiker-bottom-nav" aria-label="Navigation Kwiker"><button type="button" class="kwiker-nav-item" :class="{ 'is-active': activeSection === 'home' }" aria-label="Accueil" @click="setHome"><Home :size="21" :fill="activeSection === 'home' ? 'currentColor' : 'none'" /><span>Accueil</span></button><button type="button" class="kwiker-nav-item" aria-label="Communautés" @click="openCommunities"><Users :size="21" /><span>Communautés</span></button><button type="button" class="kwiker-nav-compose" aria-label="Créer un tweet" @click="openComposer"><PenLine :size="20" /></button><button type="button" class="kwiker-nav-item" :class="{ 'is-active': activeSection === 'bookmarks' }" aria-label="Signets" @click="setBookmarks"><Bookmark :size="21" :fill="activeSection === 'bookmarks' ? 'currentColor' : 'none'" /><span>Signets</span></button><button type="button" class="kwiker-nav-item" aria-label="Profil" @click="openOwnProfile"><UserRound :size="21" /><span>Profil</span></button></nav>
        </template>

<Transition name="kwiker-page"><section v-if="isProfileVisible" class="kwiker-page"><header class="kwiker-page-header"><button type="button" aria-label="Retour" @click="closeProfile"><ArrowLeft :size="19" /></button><strong>Profil</strong><button v-if="isOwnProfile" type="button" aria-label="Réglages" @click="openSettings"><Settings :size="18" /></button><span v-else class="kwiker-header-spacer"></span></header><div class="kwiker-page-scroll"><div class="kwiker-profile-cover"></div><div class="kwiker-profile-intro"><span class="kwiker-avatar kwiker-avatar--profile" :style="{ background: profileIdentity.color }">{{ profileIdentity.initials }}</span><div class="kwiker-profile-actions"><template v-if="isOwnProfile"><button type="button" class="kwiker-edit-button" @click="openAccountEditor">Modifier</button></template><button v-else type="button" class="kwiker-follow-button" :class="{ 'is-following': isFollowingViewed }" @click="toggleFollowViewed">{{ isFollowingViewed ? 'Suivi' : 'Suivre' }}</button></div><h2>{{ profileIdentity.name }}<Check v-if="profileIdentity.verified" class="kwiker-profile-verified" :size="14" /></h2><span class="kwiker-profile-handle">{{ profileIdentity.handle }}</span><span class="kwiker-profile-type">{{ profileIdentity.accountType }}</span><p>{{ profileIdentity.bio }}</p><div class="kwiker-profile-meta"><span><Globe2 :size="13" /> Los Santos</span><span>Depuis avril 2024</span></div><div class="kwiker-profile-stats"><span><strong>{{ profileIdentity.following }}</strong> abonnements</span><span><strong>{{ profileIdentity.followers }}</strong> abonnés</span></div></div><div v-if="isOwnProfile" class="kwiker-profile-tabs"><button v-for="tab in ['Kwiks', 'Réponses', 'Médias']" :key="tab" type="button" :class="{ 'is-active': profileTab === tab }" @click="profileTab = tab">{{ tab }}</button></div><div v-if="!isOwnProfile || profileTab === 'Kwiks'"><article v-for="post in profilePosts" :key="`profile-${post.id}`" class="kwiker-post kwiker-post--profile"><span class="kwiker-avatar" :style="{ background: post.color }">{{ post.initials }}</span><div class="kwiker-post-body"><header class="kwiker-post-header"><div class="kwiker-post-author"><strong>{{ post.author }}</strong><Check v-if="post.verified" class="kwiker-verified" :size="11" /><span>{{ post.handle }}</span><span>·</span><time>{{ relativeTime(post.time) }}</time></div></header><p v-if="post.text" class="kwiker-post-text">{{ post.text }}</p><img v-if="post.image" class="kwiker-post-image" :src="post.image" alt="Image publiée" /></div></article><div v-if="!profilePosts.length" class="kwiker-empty kwiker-empty--profile"><UserRound :size="24" /><strong>Aucun Kwik</strong><span>Ce profil n’a encore rien publié.</span></div></div><div v-else-if="profileTab === 'Réponses'"><article v-for="post in profileReplies" :key="`reply-${post.id}`" class="kwiker-post kwiker-post--profile"><span class="kwiker-avatar" :style="{ background: currentUser.color }">{{ currentUser.initials }}</span><div class="kwiker-post-body"><header class="kwiker-post-header"><div class="kwiker-post-author"><strong>{{ currentUser.name }}</strong><span>{{ currentUser.handle }}</span><span>·</span><time>{{ relativeTime(post.time) }}</time></div></header><p class="kwiker-reply-context">En réponse à {{ post.author }}</p><p class="kwiker-post-text">{{ post.commentsList.find((comment) => comment.author === currentUser.name)?.text }}</p></div></article><div v-if="!profileReplies.length" class="kwiker-empty kwiker-empty--profile"><MessageCircle :size="24" /><strong>Aucune réponse</strong><span>Les réponses que tu écriras apparaîtront ici.</span></div></div><div v-else><article v-for="post in profileMedia" :key="`media-${post.id}`" class="kwiker-post kwiker-post--profile"><span class="kwiker-avatar" :style="{ background: currentUser.color }">{{ currentUser.initials }}</span><div class="kwiker-post-body"><header class="kwiker-post-header"><div class="kwiker-post-author"><strong>{{ currentUser.name }}</strong><span>{{ currentUser.handle }}</span><span>·</span><time>{{ relativeTime(post.time) }}</time></div></header><p v-if="post.text" class="kwiker-post-text">{{ post.text }}</p><img class="kwiker-post-image" :src="post.image" alt="Image publiée" /></div></article><div v-if="!profileMedia.length" class="kwiker-empty kwiker-empty--profile"><ImagePlus :size="24" /><strong>Aucun média</strong><span>Les images de tes Kwiks apparaîtront ici.</span></div></div></div></section></Transition>
        <Transition name="kwiker-page"><section v-if="isNotificationsVisible" class="kwiker-page"><header class="kwiker-page-header"><button type="button" aria-label="Retour" @click="closeNotifications"><ArrowLeft :size="19" /></button><strong>Notifications</strong><span class="kwiker-header-spacer"></span></header><div class="kwiker-page-scroll kwiker-simple-scroll"><p class="kwiker-eyebrow">Activité récente</p><section class="kwiker-list-card"><div v-for="notification in notificationItems" :key="notification.id" class="kwiker-notification-row"><span class="kwiker-avatar kwiker-avatar--tiny" :style="{ background: notification.color }">{{ notification.initials }}</span><span><strong>{{ notification.title }}</strong><small>{{ notification.time }}</small></span><Bell :size="16" /></div></section></div></section></Transition>
